using HotelManagementSystem.Domain;
using Microsoft.EntityFrameworkCore;
namespace HotelManagementSystem.Infrastructure;
public static class CatalogSeeder
{
 public static async Task SeedAsync(HmsDbContext db){var cities=new[]{"Tbilisi","Batumi","Kutaisi","Kazbegi","Telavi","Mestia","Kobuleti"};var styles=new[]{"Garden","Terrace","House","Suites","Grand","View","Boutique","Heritage","Riverside","Sky"};foreach(var city in cities){var count=await db.Hotels.CountAsync(x=>x.City==city);for(var i=count+1;i<=20;i++)db.Hotels.Add(new Hotel{Name=$"{city} {styles[(i-1)%styles.Length]} {i}",Rating=3+i%3,Country="Georgia",City=city,Address=$"{10+i} {city} Central Street"});}await db.SaveChangesAsync();var types=new[]{("Compact Room",1,18,false,75m),("Classic Double",2,23,false,95m),("Breakfast Double",2,25,true,115m),("Deluxe King",2,30,true,145m),("Twin Room",2,28,true,135m),("Junior Suite",3,38,true,180m),("Family Studio",4,44,true,210m),("Family Suite",5,55,true,255m),("Panorama Suite",3,48,true,275m),("Residence",6,70,true,330m)};var hotels=await db.Hotels.Include(x=>x.Rooms).ToListAsync();foreach(var h in hotels){for(var i=h.Rooms.Count;i<10;i++){var t=types[i];db.Rooms.Add(new Room{Name=t.Item1,Capacity=t.Item2,SizeSquareMeters=t.Item3,BreakfastIncluded=t.Item4,Price=t.Item5+h.Rating*10,HotelId=h.Id});}}await db.SaveChangesAsync();var cars=new[]{("Toyota","Yaris","Economy",4,2,"Automatic","Petrol",39m),("Hyundai","Elantra","Compact",5,3,"Automatic","Petrol",49m),("Kia","Sportage","SUV",5,4,"Automatic","Petrol",69m),("Toyota","RAV4","SUV",5,4,"Automatic","Hybrid",79m),("Mercedes","Vito","Van",8,6,"Automatic","Diesel",109m),("Suzuki","Jimny","4x4",4,2,"Manual","Petrol",64m),("Volkswagen","Golf","Compact",5,3,"Manual","Petrol",46m),("BMW","X3","Premium SUV",5,4,"Automatic","Diesel",115m),("Renault","Duster","SUV",5,4,"Manual","Petrol",58m),("Ford","Transit","Van",9,7,"Manual","Diesel",119m)};foreach(var city in cities){var count=await db.Cars.CountAsync(x=>x.City==city);for(var i=count;i<20;i++){var c=cars[i%cars.Length];db.Cars.Add(new Car{City=city,Brand=c.Item1,Model=c.Item2,Category=c.Item3,Seats=c.Item4,Luggage=c.Item5,Transmission=c.Item6,Fuel=c.Item7,DailyPrice=c.Item8+(i%5)*4,Year=2021+i%5,AirConditioning=true,UnlimitedKilometers=true});}}await db.SaveChangesAsync();}
}
